// src/data/works.ts
function seedLicence(w) {
  const l = {
    presetId: "paid_both",
    previewWords: 80,
    exclusiveHours: 0,
    uses: {
      read: { permission: w.readPrice > 0 ? "paid" : "free", price: w.readPrice, attribution: true, includedInPass: true },
      ai_quote: { permission: "paid", price: w.quotePrice, attribution: true, linkBack: true, maxQuoteWords: 40 },
      ai_train: { permission: w.trainPermission, price: w.trainPrice, attribution: false },
      republish: { permission: "paid", price: w.republishPrice, attribution: true, derivatives: { translation: true, summary: true, clip: true }, royaltyShare: 0.3 }
    }
  };
  if (w.trainPermission === "no") l.presetId = "no_training";
  return l;
}
